import type { DriverCategory, InsightDataSource } from '@/types/hr-insights'
import type { ImpactMetricKey, ImpactScope } from '@/types/hr-impact'
import type { PriorityLevel } from '@/types/hr-intelligence'

/**
 * The Action Centre model.
 *
 * Two record kinds live side by side and must never be confused:
 *
 *   RecommendedAction  — generated by the intelligence engine, awaiting HR review.
 *   HrAction           — a demo action a human approved, stored in localStorage.
 *
 * The official `Action_Tracker` records from the workbook stay in `ActionRecord`
 * (`@/types/hr-data`) and are read-only. Nothing here ever writes to them.
 */

export type ActionMetricUnit = 'score' | 'percentage' | 'count'

/** A labelled measurement with its unit, so the UI never guesses the scale. */
export interface ActionMetric {
  label: string
  value: number | null
  unit: ActionMetricUnit
}

/**
 * Which likely driver a recommendation was built from. `diagnostic` is the
 * explicit no-driver case: the engine recommends validating the issue rather
 * than pretending to know which intervention will work.
 */
export type RecommendationDriverKey = DriverCategory | 'diagnostic'

export type RecommendedActionStatus = 'pending-review' | 'approved' | 'rejected'

export type ActionExecutionStatus = 'planned' | 'in-progress' | 'completed' | 'cancelled'

export interface RecommendedAction {
  id: string
  insightId: string

  title: string
  description: string

  issueTitle: string
  affectedScope: string

  driverCategory: RecommendationDriverKey
  driverLabel: string

  priorityScore: number
  priorityLevel: PriorityLevel

  suggestedOwner: string
  suggestedDurationDays: number

  baselineMetric: ActionMetric
  suggestedTarget: ActionMetric

  /**
   * Which repeatable survey measure the baseline came from, and the workforce
   * slice it was taken from. Recorded structurally at generation time so the
   * Impact Tracker can find a later reading of the *same* measure over the
   * *same* population — rather than parsing a display label after the fact.
   * Absent when the baseline is the issue's headline metric, which this
   * prototype does not map to a repeatable measure.
   */
  impactMetricKey?: ImpactMetricKey
  impactScope?: ImpactScope

  successMeasure: string

  rationale: string
  evidenceSources: InsightDataSource[]

  reviewStatus: RecommendedActionStatus
}

export interface HrAction {
  id: string
  sourceRecommendationId?: string
  /** Links back to `/insights/:insightId` for the original analysis. */
  insightId?: string

  title: string
  description: string

  issueTitle: string
  affectedScope: string

  /** Priority of the underlying issue when the action was approved. */
  priorityScoreAtCreation?: number
  priorityLevelAtCreation?: PriorityLevel

  owner: string

  startDate: string
  dueDate: string

  successMeasure: string

  baselineMetric?: ActionMetric
  targetMetric?: ActionMetric

  /** Carried over from the recommendation, so impact survives a refresh. */
  impactMetricKey?: ImpactMetricKey
  impactScope?: ImpactScope

  status: ActionExecutionStatus

  /** True when HR changed any suggested value before approving. */
  editedByHr: boolean

  createdAt: string
  updatedAt: string
  /** Set the first time the status becomes `completed`. */
  completedAt?: string
}

/** The editable form values in the HR review panel. Strings bind to inputs. */
export interface ActionReviewDraft {
  title: string
  description: string
  owner: string
  startDate: string
  dueDate: string
  successMeasure: string
  targetValue: string
}

/** What HR decided about one recommendation, persisted separately from actions. */
export interface RecommendationReview {
  status: RecommendedActionStatus
  reviewedAt: string
  rejectionReason?: string
}

export type RecommendationReviewMap = Record<string, RecommendationReview>
